class Solution {
  private List<Integer>[] graph;
  private int target, seconds;

  public double frogPosition(int n, int[][] edges, int t, int target) {
    graph = new List[n + 1];
    for (int i = 1; i <= n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
      graph[e[0]].add(e[1]);
      graph[e[1]].add(e[0]);
    }
    this.target = target;
    this.seconds = t;
    return dfs(1, 0, 0, 1.0);
  }

  private double dfs(int node, int parent, int time, double probability) {
    int children = graph[node].size() - (parent == 0 ? 0 : 1);
    if (node == target) {
      // the frog must be there at exactly t, or be stuck there on a leaf earlier
      return time == seconds || (time < seconds && children == 0) ? probability : 0;
    }
    if (time == seconds) return 0;
    for (int next : graph[node]) {
      if (next == parent) continue;
      double found = dfs(next, node, time + 1, probability / children);
      if (found > 0) return found;
    }
    return 0;
  }
}
